import {parsePGN,prepare} from './chess.js';
const $=id=>document.getElementById(id), glyph={K:'♚',Q:'♛',R:'♜',B:'♝',N:'♞',P:'♟'};
let builtin={},games=[],bag=[],current=null,idx=0,playing=true,timer=null,wake=null;let imported=[];
const settings=$('settings'),collection=$('collection'),order=$('order'),speed=$('speed'),hold=$('hold');
function clean(v){return v&&v!=='?'&&!v.includes('??')?v:''}function player(v){if(!v)return 'Unknown player';let a=v.split(',');return a.length>1?`${a.slice(1).join(',').trim()} ${a[0].trim()}`:v}
function formatDate(v){if(!v||v.includes('?'))return '';let [y,m,d]=v.split('.').map(Number);if(!y||!m||!d)return v.replaceAll('.',' ');return new Date(y,m-1,d).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}
function makeBag(){bag=[...games.keys()];if(order.value==='shuffle')for(let i=bag.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}}
function nextGame(){if(!games.length)return;if(!bag.length){let previous=current;makeBag();if(bag.length>1&&games[bag[0]]===previous)[bag[0],bag[1]]=[bag[1],bag[0]]}current=games[bag.shift()];idx=0;render();schedule()}
const portraitPhotos={fischer:'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Bobby_Fischer_1972.jpg/250px-Bobby_Fischer_1972.jpg',spassky:'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/IBM-schaaktoernooi_Boris_Spasski%2C_Bestanddeelnr_923-7139.jpg/330px-IBM-schaaktoernooi_Boris_Spasski%2C_Bestanddeelnr_923-7139.jpg',gukesh:'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Gukesh_in_2024_%28cropped%29.jpg/250px-Gukesh_in_2024_%28cropped%29.jpg',sindarov:'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Javokhir_Sindarov_%28cropped%29.jpg/250px-Javokhir_Sindarov_%28cropped%29.jpg',carlsen:'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/World_Chess_Championship_2021%2C_game_07%2C_Magnus_Carlsen_%28cropped%29.jpg/250px-World_Chess_Championship_2021%2C_game_07%2C_Magnus_Carlsen_%28cropped%29.jpg',anand:'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Viswanathan_Anand_%28cropped%29.jpg/250px-Viswanathan_Anand_%28cropped%29.jpg',karjakin:'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Karjakin_Sergey_%2830334901886%29_%28cropped%29.jpg/250px-Karjakin_Sergey_%2830334901886%29_%28cropped%29.jpg',caruana:'https://upload.wikimedia.org/wikipedia/commons/0/02/Caruana_at_the_FIDE_World_FR_Chess_Championship_2019_%28cropped_v2%29.jpg',nepomniachtchi:'https://upload.wikimedia.org/wikipedia/commons/6/67/World_Chess_Championship_2021%2C_game_07%2C_Ian_Nepomniachtchi_%28cropped%29.jpg',ding:'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Ding_Liren_in_2024_%28cropped%29.jpg/250px-Ding_Liren_in_2024_%28cropped%29.jpg'};
function setPortrait(id,name){let el=$(id),key=/\bfischer\b/i.test(name||'')?'fischer':/\bspassk(?:y|i)\b/i.test(name||'')?'spassky':/\bgukesh\b/i.test(name||'')?'gukesh':/\bsindarov\b/i.test(name||'')?'sindarov':/\bcarlsen\b/i.test(name||'')?'carlsen':/\banand\b/i.test(name||'')?'anand':/\bkarjakin\b/i.test(name||'')?'karjakin':/\bcaruana\b/i.test(name||'')?'caruana':/\bnepomniachtchi\b/i.test(name||'')?'nepomniachtchi':/\b(?:ding|liren)\b/i.test(name||'')?'ding':null;if(el.dataset.player===String(key))return;el.dataset.player=String(key);el.querySelector('img')?.remove();el.classList.remove('has-photo');if(!key)return;let img=document.createElement('img');img.alt='';img.decoding='async';img.className=key;img.onload=()=>{if(img.isConnected)el.classList.add('has-photo')};img.onerror=()=>{if(img.isConnected){img.remove();el.classList.remove('has-photo')}};img.src=portraitPhotos[key];el.append(img)}
function render(){if(!current)return;let {tags,moves,positions}=current,p=positions[idx],board=$('board');board.replaceChildren();p.state.b.forEach((piece,i)=>{let square=document.createElement('div');square.className='square'+(((Math.floor(i/8)+i%8)%2)?' dark-square':'')+((i===p.from||i===p.to)?' last':'');if(i%8===0||i>=56){let c=document.createElement('span');c.className='coord';c.textContent=(i%8===0?String(8-Math.floor(i/8)):'')+(i>=56?'abcdefgh'[i%8]:'');square.append(c)}if(piece){let q=document.createElement('img');q.className='piece '+(piece===piece.toUpperCase()?'white':'black');q.src=`pieces/w${piece.toUpperCase()}.svg`;q.alt='';q.draggable=false;square.append(q);if(i===p.to&&p.from!==null&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){let dx=(p.from%8)-(p.to%8),dy=Math.floor(p.from/8)-Math.floor(p.to/8);q.animate([{transform:`translate(${dx*100}%, ${dy*100}%)`},{transform:'translate(0,0)'}],{duration:300,easing:'ease-out'})}}board.append(square)});$('event').textContent=clean(tags.Event)||'Chess game';$('meta').textContent=[clean(tags.Site),formatDate(tags.Date),clean(tags.EventType),clean(tags.Round)?`Game ${tags.Round}`:''].filter(Boolean).join('  ·  ');$('whiteName').textContent=player(tags.White);$('blackName').textContent=player(tags.Black);setPortrait('whitePortrait',tags.White);setPortrait('blackPortrait',tags.Black);$('whiteClock').textContent=p.clocks[0]||'';$('blackClock').textContent=p.clocks[1]||'';$('moveLabel').textContent=idx?`MOVE ${Math.ceil(idx/2)}${idx%2?' · WHITE':' · BLACK'}  ${moves[idx-1].san}`:'STARTING POSITION';$('gamecount').textContent=`${games.length} ${games.length===1?'GAME':'GAMES'} IN COLLECTION`;$('result').textContent=idx===moves.length?`FINAL RESULT  ·  ${tags.Result==='1/2-1/2'?'½ – ½':(clean(tags.Result)||'Unknown')}`:'THE GAME IS UNDERWAY';$('progressFill').style.width=`${idx/moves.length*100}%`;$('toggle').textContent=playing?'❚❚':'▶';$('toggle').setAttribute('aria-label',playing?'Pause':'Play')}
function schedule(){clearTimeout(timer);if(!playing||settings.open||!current)return;timer=setTimeout(()=>{if(idx<current.moves.length){idx++;render();schedule()}else nextGame()},(idx===current.moves.length?+hold.value:+speed.value)*1000)}
async function keepAwake(){try{if('wakeLock'in navigator)wake=await navigator.wakeLock.request('screen')}catch{}}
async function loadCollection(){let key=collection.value;let source=key==='imported'?imported:key==='all'?Object.values(builtin).flat():key==='carlsen'?[2013,2014,2016,2018,2021].flatMap(y=>builtin['world'+y]):key==='ding'?[2023,2024].flatMap(y=>builtin['world'+y]):builtin[key]||[];let errors=[];games=[];for(const g of source){try{games.push(prepare(g))}catch(e){errors.push(`${g.tags.Event||'Game'}: ${e.message}`)}}$('notice').textContent=errors.length?`${games.length} playable; ${errors.length} could not be read. ${errors[0]}`:'';if(!games.length){$('notice').textContent='No playable standard chess games found. Choose another collection or file.';return false}bag=[];playing=true;nextGame();return true}
$('settingsButton').onclick=$('openSettings').onclick=()=>{clearTimeout(timer);settings.showModal();collection.focus()};settings.addEventListener('close',schedule);$('apply').onclick=()=>{if(loadCollection()){settings.close();keepAwake()}};$('toggle').onclick=()=>{playing=!playing;render();schedule();if(playing)keepAwake()};$('prev').onclick=()=>{playing=false;idx=Math.max(0,idx-1);render();schedule()};$('next').onclick=()=>{playing=false;idx=Math.min(current.moves.length,idx+1);render();schedule()};$('skip').onclick=()=>{playing=true;nextGame()};speed.oninput=()=>$('speedValue').textContent=speed.value;hold.oninput=()=>$('holdValue').textContent=hold.value;
$('file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let t=await f.text();imported=parsePGN(t);if(!imported.length){$('notice').textContent='No playable standard-chess games found in that file.';return}$('importOption').disabled=false;$('importOption').textContent=`${f.name} · ${imported.length} games`;collection.value='imported';$('notice').textContent=`Loaded ${imported.length} game records. Choose Start playing.`;try{localStorage.setItem('chess-jukebox-pgn',t)}catch{}}catch{$('notice').textContent='Unable to read that file.'}};
document.addEventListener('keydown',e=>{if(settings.open)return;if(e.key==='ArrowLeft'){e.preventDefault();$('prev').click()}else if(e.key==='ArrowRight'){e.preventDefault();$('next').click()}else if(e.key===' '||e.key==='MediaPlayPause'){e.preventDefault();$('toggle').click()}else if(e.key==='Escape'||e.key==='Backspace'){$('settingsButton').click()}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&playing)keepAwake()});
try{let saved=localStorage.getItem('chess-jukebox-pgn');if(saved){imported=parsePGN(saved);if(imported.length){$('importOption').disabled=false;$('importOption').textContent=`Imported PGN · ${imported.length} games`}}}catch{}
try{let names=['fischer','gukesh','world2013','world2014','world2016','world2018','world2021','world2023','world2024'];let responses=await Promise.all(names.map(x=>fetch(`${x}.pgn`).then(r=>{if(!r.ok)throw Error('Could not load the included games');return r.text()})));builtin=Object.fromEntries(names.map((name,i)=>[name,parsePGN(responses[i])]));await loadCollection();keepAwake()}catch(e){$('result').textContent='UNABLE TO LOAD THE INCLUDED GAMES';console.error(e)}
